'use strict';
/* Scheduled report summaries for the CEO, shown in the admin panel (no e-mail, no outside service).
 * - Schedule: weekly (default), every two weeks, or off; set by the CEO or admin, changes go into the audit log.
 * - A report is generated by the daily cron entry point, or by the first visit to the reports page once one is due
 *   (catch-up), so a missed cron run never loses a report. A database index allows one scheduled report per day,
 *   so two server instances cannot both write it. "Generate now" adds an on-demand report.
 * - Contents: coverage, quantified findings (PKR, hours, kg/lb, with the calculation) over the rolling 30 days the
 *   dashboard and alerts use, plus the period's alerts, corrective actions and record activity, and the change since
 *   the previous report. All from approved records. */
const M = require('../js/measure.js');
const D = require('../js/data.js');
const audit = require('./audit');
const { HttpError } = require('./errors');

const SCHEDULES = { weekly: 7, biweekly: 14, off: 0 };
const SCHEDULE_KEY = 'report_schedule';
const STAGES = ['detected', 'diagnosed', 'approved', 'in_progress', 'verified'];

const addDays = (d, n) => new Date(Date.parse(`${d}T00:00:00Z`) + n * 864e5).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 864e5);
const pkr = n => {
  const a = Math.abs(n);
  return a >= 1e9 ? `PKR ${(n / 1e9).toFixed(2)}B` : a >= 1e6 ? `PKR ${(n / 1e6).toFixed(1)}M` : a >= 1e3 ? `PKR ${(n / 1e3).toFixed(1)}K` : `PKR ${Math.round(n)}`;
};

/** The report itself: a pure function of the measured output and the period's activity. */
function buildSummary(out, { from, to, days, alerts, actions, records, previous }) {
  const findings = out.findings;
  const top = findings.slice(0, 10).map(f => ({ key: f.key, name: f.name, sec: f.sec, value: f.value, target: f.target, unit: f.unit, status: f.status, n: f.n, gapPct: f.gapPct, quant: f.quant }));
  const bySection = {};
  for (const f of findings) {
    const s = bySection[f.sec] || (bySection[f.sec] = { name: (D.SECTIONS[f.sec] || {}).name || f.sec, findings: 0, high: 0, pkr: 0 });
    s.findings++;
    if (f.status === 'bad') s.high++;
  }
  // PKR per section counts each overlap group once, like the totals.
  const once = new Map();
  for (const f of findings) {
    if (!f.quant || !f.quant.pkr) continue;
    const g = `${f.sec}|${f.quant.overlap || f.key}`;
    once.set(g, Math.max(once.get(g) || 0, f.quant.pkr));
  }
  for (const [g, v] of once) bySection[g.split('|')[0]].pkr += v;
  const byStage = Object.fromEntries(STAGES.map(s => [s, 0]));
  let overdue = 0;
  const verified = [];
  for (const a of actions) {
    byStage[a.stage] = (byStage[a.stage] || 0) + 1;
    if (a.stage !== 'verified' && a.due < to) overdue++;
    if (a.stage === 'verified' && a.updated_at >= `${from}T00:00:00.000Z`) verified.push(a.id);
  }
  const change = previous ? {
    since: previous.period.to,
    pkr: out.totals.pkr - ((previous.totals && previous.totals.pkr) || 0),
    coveragePct: +(out.coverage.pct - ((previous.coverage && previous.coverage.pct) || 0)).toFixed(1),
    findings: findings.length - ((previous.topFindingsCount !== undefined ? previous.topFindingsCount : (previous.topFindings || []).length)),
  } : null;
  const summary = {
    period: { from, to, days },
    coverage: { pct: out.coverage.pct, measured: out.coverage.measured, applicable: out.coverage.applicable, records: out.coverage.records },
    totals: out.totals,
    findingsCount: findings.length,
    topFindingsCount: findings.length,
    high: findings.filter(f => f.status === 'bad').length,
    medium: findings.filter(f => f.status === 'warn').length,
    topFindings: top,
    bySection,
    alerts,
    actions: { byStage, overdue, verified },
    records,
    change,
  };
  const parts = [
    `${out.coverage.pct}% of KPIs measured over the last 30 days`,
    `${records.approved} record${records.approved === 1 ? '' : 's'} approved this period`,
    findings.length ? `${findings.length} off target (${summary.high} high, ${summary.medium} medium)${out.totals.pkr ? `, ${pkr(out.totals.pkr)} at risk per 30 days` : ''}` : 'every measured KPI on target',
    `${alerts.openHigh} high and ${alerts.openMedium} medium alerts open`,
    `${verified.length} fix${verified.length === 1 ? '' : 'es'} verified`,
  ];
  return { summary, headline: `${parts.join('; ')}.` };
}

function makeReports(db, clock, { records, actions, alerts, usage }) {
  const iso = () => new Date(clock()).toISOString();
  const today = () => iso().slice(0, 10);

  async function schedule() {
    const r = await db.get('SELECT v FROM settings WHERE k = ?', [SCHEDULE_KEY]);
    return r && SCHEDULES[r.v] !== undefined ? r.v : 'weekly';
  }
  async function setSchedule(user, value) {
    if (typeof value !== 'string' || !Object.prototype.hasOwnProperty.call(SCHEDULES, value)) throw new HttpError(400, `schedule must be one of ${Object.keys(SCHEDULES).join(', ')}.`);
    const before = await schedule();
    await db.tx(async t => {
      const now = iso();
      await t.run('INSERT INTO settings (k, v, updated_at, updated_by) VALUES (?, ?, ?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v, updated_at = excluded.updated_at, updated_by = excluded.updated_by', [SCHEDULE_KEY, value, now, user.id]);
      await audit.append(t, { ts: now, user, action: 'report.schedule_changed', target: null, detail: { from: before, to: value, msg: `${user.username} set the CEO report to ${value}` } });
    });
    return { schedule: value, nextDue: await nextDue() };
  }
  async function lastScheduled() {
    return db.get("SELECT period_to, summary FROM reports WHERE kind = 'scheduled' ORDER BY period_to DESC LIMIT 1");
  }
  async function nextDue() {
    const days = SCHEDULES[await schedule()];
    if (!days) return null;
    const last = await lastScheduled();
    return last ? addDays(last.period_to, days) : today();
  }

  /** Generate one report covering the `days` days up to today. Returns the stored report, or null if another
   *  instance already wrote today's scheduled one. */
  async function generate(user, kind, days, sched) {
    const to = today();
    const from = addDays(to, -(days - 1));
    const t0 = performance.now();
    // KPIs, findings and money are measured over the same rolling 30 days as the dashboard and the alerts (monthly
    // records would otherwise drop out of a weekly report); the period itself governs the activity counts.
    const recs = await records.approvedSince(M.windowFor('m', to).from);
    const actionRows = await db.all('SELECT id, stage, due, updated_at FROM actions');
    const fromIso = `${from}T00:00:00.000Z`;
    const rec = await db.get(`SELECT SUM(CASE WHEN status IN ('approved', 'voided') AND reviewed_at >= ? THEN 1 ELSE 0 END) AS approved,
      SUM(CASE WHEN status = 'rejected' AND reviewed_at >= ? THEN 1 ELSE 0 END) AS rejected,
      SUM(CASE WHEN submitted_at >= ? THEN 1 ELSE 0 END) AS entered, SUM(CASE WHEN status = 'submitted' THEN 1 ELSE 0 END) AS waiting FROM records`, [fromIso, fromIso, fromIso]);
    const alertStats = await alerts.periodStats(fromIso);
    const prev = await db.get('SELECT summary FROM reports ORDER BY id DESC LIMIT 1');
    const t1 = performance.now();
    const out = M.measureAll(recs, { plant: 'all', period: 'm', today: to });
    const { summary, headline } = buildSummary(out, {
      from, to, days, alerts: alertStats, actions: actionRows,
      records: { approved: rec.approved || 0, rejected: rec.rejected || 0, entered: rec.entered || 0, waiting: rec.waiting || 0 },
      previous: prev ? JSON.parse(prev.summary) : null,
    });
    const t2 = performance.now();
    const ms = Math.round(t2 - t0);
    const id = await db.tx(async t => {
      const now = iso();
      const r = await t.run(`INSERT INTO reports (kind, schedule, period_from, period_to, created_at, created_by, headline, summary, ms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT DO NOTHING`, [kind, sched, from, to, now, user ? user.id : null, headline, JSON.stringify(summary), ms]);
      if (!r.changes) return null;
      await audit.append(t, { ts: now, user: user || null, action: 'report.generated', target: `report:${r.lastInsertRowid}`, detail: { kind, from, to, msg: `${kind === 'scheduled' ? 'Scheduled' : 'On-demand'} report for ${from} to ${to}` } });
      return r.lastInsertRowid;
    });
    await usage.log('report', { ms: t2 - t0, gatherMs: t1 - t0, computeMs: t2 - t1, detail: { kind, days, records: recs.length } });
    return id ? one(id) : null;
  }

  /** Generate the scheduled report if one is due (catch-up safe). Returns it, or null when nothing was due. */
  async function runDue() {
    const sched = await schedule();
    const days = SCHEDULES[sched];
    if (!days) return null;
    const last = await lastScheduled();
    if (last && daysBetween(last.period_to, today()) < days) return null;
    return generate(null, 'scheduled', days, sched);
  }
  async function generateNow(user) {
    const sched = await schedule();
    return generate(user, 'manual', SCHEDULES[sched] || 7, sched);
  }

  const SELECT = 'SELECT r.*, u.username AS by_user FROM reports r LEFT JOIN users u ON u.id = r.created_by';
  const head = r => ({ id: r.id, kind: r.kind, schedule: r.schedule, from: r.period_from, to: r.period_to, createdAt: r.created_at, createdBy: r.by_user || 'scheduler', headline: r.headline, ms: r.ms });
  async function list(limit = 52) {
    return (await db.all(`${SELECT} ORDER BY r.id DESC LIMIT ?`, [Math.min(200, Math.max(1, limit))])).map(head);
  }
  async function one(id) {
    const r = await db.get(`${SELECT} WHERE r.id = ?`, [id]);
    if (!r) throw new HttpError(404, 'No such report.');
    return { ...head(r), summary: JSON.parse(r.summary) };
  }

  return { schedule, setSchedule, nextDue, runDue, generateNow, list, one };
}

module.exports = { makeReports, buildSummary, SCHEDULES };
